import type { DashboardData } from "../../../shared/types/dashboard";
import { BffConnectionFactory } from "../../../shared/infrastructure/bff/BffConnectionFactory";
import { DashboardEndpoint } from "./dashboardEndpoints";

const bffConnection = BffConnectionFactory.create();

export async function getDashboard(): Promise<DashboardData> {
  return bffConnection.get<DashboardData>(DashboardEndpoint.Dashboard);
}
