"use client";

import { useEffect, useState } from "react";
import { PageWrap } from "../../../shared/components/PageWrap";
import type { DashboardData } from "../../../shared/types/dashboard";
import { getDashboard } from "../api/dashboardApi";
import { CurrentSessionCard } from "../components/CurrentSessionCard";
import { DashboardHeader } from "../components/DashboardHeader";
import { ProductivityStats } from "../components/ProductivityStats";
import { TaskListCard } from "../components/TaskListCard";
import { AppShell } from "@/shared/components/AppShell";

export function DashBoardPageView() {
  const [data, setData] = useState<DashboardData | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  async function loadDashboard() {
    setIsLoading(true);
    setError(null);

    try {
      setData(await getDashboard());
    } catch {
      setError(
        "O BFF não respondeu. Verifique se o servidor está rodando na porta 9000.",
      );
    } finally {
      setIsLoading(false);
    }
  }

  useEffect(() => {
    void loadDashboard();
  }, []);

  return (
    <AppShell>
      <PageWrap id="overview">
        {data ? <DashboardHeader greeting={data.greeting} /> : null}

        {isLoading && (
          <div className="alert alert-light border">
            Carregando seu ritmo...
          </div>
        )}

        {error && (
          <div className="alert alert-warning d-flex justify-content-between align-items-center">
            <span>{error}</span>
            <button
              className="btn btn-sm btn-outline-dark"
              onClick={() => void loadDashboard()}
            >
              Tentar novamente
            </button>
          </div>
        )}

        {data && (
          <>
            <ProductivityStats stats={data.stats} />

            <section className="row g-4">
              <div className="col-lg-7" id="sessions">
                <CurrentSessionCard />
              </div>
              <div className="col-lg-5" id="tasks">
                <TaskListCard tasks={data.tasks} />
              </div>
            </section>
          </>
        )}
      </PageWrap>
    </AppShell>
  );
}
