import type { DashboardTask } from "../../../shared/types/dashboard";

type TaskListCardProps = {
  tasks: DashboardTask[];
};

export function TaskListCard({ tasks }: TaskListCardProps) {
  return (
    <div className="surface-card task-card">
      <div className="d-flex justify-content-between align-items-center mb-4">
        <div>
          <p className="eyebrow">PARA HOJE</p>
          <h2>Suas tarefas</h2>
        </div>
        <button className="link-button">Ver todas</button>
      </div>

      {tasks.map((task) => (
        <div className="task-row" key={task.id}>
          <span className={`task-check ${task.completed ? "completed" : ""}`}>
            {task.completed ? <i className="bi bi-check-lg" aria-hidden="true" /> : null}
          </span>
          <div>
            <strong className={task.completed ? "done" : ""}>{task.title}</strong>
            <small>{task.category}</small>
          </div>
        </div>
      ))}
    </div>
  );
}
