import { StatCard } from "../../../shared/components/StatCard";
import type { DashboardStats } from "../../../shared/types/dashboard";

type ProductivityStatsProps = {
  stats: DashboardStats;
};

export function ProductivityStats({ stats }: ProductivityStatsProps) {
  const items = [
    {
      label: "Tempo em foco",
      value: `${stats.focusMinutes} min`,
      helper: "+12% vs. ontem",
      tone: "blue" as const,
      icon: "bi-stopwatch-fill",
    },
    {
      label: "Sessões concluídas",
      value: String(stats.completedSessions),
      helper: "Meta diária: 6 sessões",
      tone: "orange" as const,
      icon: "bi-check-circle-fill",
    },
    {
      label: "Ritmo semanal",
      value: `${stats.weeklyChange}%`,
      helper: "Você está acima da média",
      tone: "green" as const,
      icon: "bi-graph-up-arrow",
    },
  ];

  return (
    <section className="row g-3 mb-4" aria-label="Resumo de produtividade">
      {items.map((item) => (
        <div className="col-md-4" key={item.label}>
          <StatCard
            label={item.label}
            value={item.value}
            helper={item.helper}
            tone={item.tone}
            icon={item.icon}
          />
        </div>
      ))}
    </section>
  );
}
